<?php use Pjas\Http\{Csrf,View}; ?>
<h1>公開前の確認</h1><p class="sub"><?= View::e($service['name']) ?>に公開するファイルを準備しました。まだ本番は変更していません。</p>
<div class="grid4"><?php foreach(['added'=>'追加','modified'=>'変更','deleted'=>'削除'] as $key=>$label):?><div class="card kpi"><div class="n"><?= $plan['counts'][$key] ?></div><div class="l"><?= $label ?>するファイル</div></div><?php endforeach;?></div>
<?php foreach($plan['warnings'] as $warning):?><div class="note err"><?= View::e($warning) ?></div><?php endforeach;?>
<div class="note">設定やDBなどの共有データは既存の内容を優先します。公開直前にバックアップを保存します。ビルドなどの準備処理が生成する成果物は、このファイル一覧には含まれません。</div>
<details class="card" style="margin-top:16px"><summary class="card-h">ファイルごとの変更点を見る（最大1,000件）</summary><table><thead><tr><th>種類</th><th>ファイル</th><th></th></tr></thead><tbody><?php foreach($plan['changes'] as $change):?><tr><td><span class="tag <?= $change['status']==='deleted'?'t-err':($change['status']==='added'?'t-ok':'t-warn') ?>"><?= ['added'=>'追加','modified'=>'変更','deleted'=>'削除'][$change['status']] ?></span></td><td class="mono"><?= View::e($change['path']) ?></td><td><a class="btn sm" href="/services/<?= View::e($service['name']) ?>/review-file?token=<?= View::e($plan['token']) ?>&amp;path=<?= urlencode($change['path']) ?>">差分を見る</a></td></tr><?php endforeach;?></tbody></table></details>
<div class="card" style="margin-top:16px"><div class="card-h">いつ公開しますか？</div><div class="card-b"><form method="post" action="/deploy/confirm"><?= Csrf::field() ?><input type="hidden" name="service" value="<?= View::e($service['name']) ?>"><input type="hidden" name="token" value="<?= View::e($plan['token']) ?>"><input type="hidden" name="label" value="<?= View::e($options['label']) ?>"><?php if($options['auto_rollback']):?><input type="hidden" name="auto_rollback" value="1"><?php endif;?><?php if($options['maintenance']):?><input type="hidden" name="maintenance" value="1"><?php endif;?>
<div class="field"><label for="publication-mode">公開する時刻</label><select id="publication-mode" name="publication_mode"><option value="now">確認した内容を今すぐ公開する</option><option value="scheduled">日時を指定して予約する</option></select></div><div class="field" id="publication-time" hidden><label>公開日時（日本時間）</label><input type="datetime-local" name="publish_at"><div class="hint">1分後から30日以内で指定できます。予約後に本番コードやサイト設定が変わった場合は、安全のため公開を止めます。</div></div>
<div class="row"><button class="btn p">確認した内容で実行する</button><a class="btn" href="/services/<?= View::e($service['name']) ?>/operations?section=preview&amp;token=<?= View::e($plan['token']) ?>">先に試験用URLで確かめる</a></div></form></div></div>
<script src="/assets/publication.js" defer></script>
